-- HEN-183 (M2-13): the sign-up attestation is a consent record too (ARCHITECTURE.md §2.4), in the table 003 created.
-- It stores the text version id the user accepted and when; never the wording, never age answers. Like the age
-- confirmation it is append-only for the app (a new text version means a new row) and goes with the account
-- (ON DELETE CASCADE from 003). Do not edit this file once applied; extend it in a new migration.

ALTER TABLE public.consent_records DROP CONSTRAINT consent_records_consent_type_check;

ALTER TABLE public.consent_records
  ADD CONSTRAINT consent_records_consent_type_check CHECK (consent_type IN ('age_confirmation', 'attestation_signup'));

ALTER TABLE public.consent_records
  ADD CONSTRAINT consent_records_attestation_signup_no_answers CHECK (
    consent_type <> 'attestation_signup' OR (age16_confirmed IS NULL AND age18_confirmed IS NULL)
  );
